/**
 * The workspace price list (the {@code price_list_rate} table): a price in US dollars per unit type,
 * a single price or tiers (see {@link RateTiers}), for unit types a client's own rate card doesn't
 * cover. A line priced from it gets each price, or each band's price, converted into the client's
 * currency at the rates on the invoice's issue date, rounded down to the currency's step.
 */
@Service
public class PriceList {

    private final JdbcTemplate jdbc;
    private final ExchangeRates exchangeRates;

    public PriceList(JdbcTemplate jdbc, ExchangeRates exchangeRates) {
        this.jdbc = jdbc;
        this.exchangeRates = exchangeRates;
    }

    /** An entry of the price list: its unit type and a single unit price or tiers, in US dollars. */
    public record Entry(String unitType, BigDecimal unitPrice, RateTiers tiers) {
    }

    /** A price converted into a client's currency: a single unit price, or tiers in their stored form. */
    public record Converted(BigDecimal unitPrice, String tiers) {
    }

    /** Every entry, by unit type. */
    public List<Entry> all() {
        return jdbc.query("SELECT unit_type, unit_price, tiers FROM price_list_rate ORDER BY unit_type",
                (rs, n) -> new Entry(rs.getString(1), rs.getBigDecimal(2), RateTiers.parse(rs.getString(3))));
    }

    /** Adds an entry: a single unit price, or tiers. */
    public void add(String unitType, BigDecimal unitPrice, RateTiers tiers) {
        jdbc.update("INSERT INTO price_list_rate (unit_type, unit_price, tiers) VALUES (?, ?, ?)", unitType,
                tiers == null ? unitPrice : null, tiers == null ? null : tiers.format());
    }

    /**
     * The price list's price for the unit type (matched ignoring case) converted into the currency at
     * the rates on the date, or null when the price list has none.
     */
    public Converted priceFor(String unitType, Currency currency, LocalDate on) {
        List<Map<String, Object>> found = jdbc.queryForList(
                "SELECT unit_price, tiers FROM price_list_rate WHERE LOWER(unit_type) = LOWER(?)", unitType.trim());
        if (found.isEmpty()) {
            return null;
        }
        RateTiers tiers = RateTiers.parse((String) found.get(0).get("TIERS"));
        if (tiers != null) {
            RateTiers converted = new RateTiers(tiers.bands().stream()
                    .map(b -> new RateTiers.Band(b.units(), convert(b.unitPrice(), currency, on))).toList());
            return new Converted(converted.firstPrice(), converted.format());
        }
        return new Converted(convert((BigDecimal) found.get(0).get("UNIT_PRICE"), currency, on), null);
    }

    private BigDecimal convert(BigDecimal usd, Currency currency, LocalDate on) {
        return exchangeRates.convert(usd, Currency.USD, currency, on);
    }
}
package net.officefloor.hq.app.clients;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.math.BigDecimal;

/** An entry of a client's rate card: a single unit price, or progressive tiers (see {@link RateTiers}). */
@Embeddable
public class ClientRate {

    /** The single unit price; null when priced in tiers. */
    @Column(name = "unit_price")
    private BigDecimal unitPrice;

    /** The tiers in their stored form; null for a single unit price. */
    @Column(name = "tiers")
    private String tiers;

    /** The increment the unit type is billed in (0.25 of an hour, packs of 5); null for none. */
    @Column(name = "increment")
    private BigDecimal increment;

    /** The minimum units the unit type is billed (a call-out is at least 2 hours); null for none. */
    @Column(name = "min_units")
    private BigDecimal minUnits;

    /**
     * The unit type's own tax percentage, charged on its lines instead of the client's regional or workspace
     * rate unless a line has a rate of its own; null for none.
     */
    @Column(name = "tax_rate")
    private BigDecimal taxRate;

    protected ClientRate() {
    }

    /** A single unit price, billed in the given increment and minimum units (null for none). */
    public ClientRate(BigDecimal unitPrice, BigDecimal increment, BigDecimal minUnits) {
        this.unitPrice = unitPrice;
        this.increment = increment;
        this.minUnits = minUnits;
    }

    /** A single unit price, billed in the given increment and minimum units and taxed at the given rate (null for none). */
    public ClientRate(BigDecimal unitPrice, BigDecimal increment, BigDecimal minUnits, BigDecimal taxRate) {
        this(unitPrice, increment, minUnits);
        this.taxRate = taxRate;
    }

    public BigDecimal getUnitPrice() {
        return unitPrice;
    }

    public BigDecimal getIncrement() {
        return increment;
    }

    public BigDecimal getMinUnits() {
        return minUnits;
    }

    /** The unit type's own tax percentage; null for none. */
    public BigDecimal getTaxRate() {
        return taxRate;
    }

    /** The tiers; null for a single unit price. */
    public RateTiers tiers() {
        return RateTiers.parse(tiers);
    }
}
package net.officefloor.hq.app.clients;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

/**
 * A unit type priced in progressive tiers, like tax brackets: bands of units each with its own unit
 * price, the last band (with no units) covering everything above. Stored as "units:unitPrice" joined
 * by semicolons, the last band with no units ("10:20.00;40:15.00;:12.00").
 */
public record RateTiers(List<Band> bands) {

    /** A band: its number of units (null for the last band, everything above) and their unit price. */
    public record Band(BigDecimal units, BigDecimal unitPrice) {
    }

    /** The tiers in the stored form; null when there are none. */
    public static RateTiers parse(String stored) {
        if (stored == null || stored.isBlank()) {
            return null;
        }
        List<Band> bands = new ArrayList<>();
        for (String band : stored.split(";")) {
            String[] parts = band.split(":", 2);
            bands.add(new Band(parts[0].isBlank() ? null : new BigDecimal(parts[0]), new BigDecimal(parts[1])));
        }
        return new RateTiers(bands);
    }

    /** The stored form of the tiers. */
    public String format() {
        return String.join(";", bands.stream()
                .map(b -> (b.units() == null ? "" : b.units().toPlainString()) + ":" + b.unitPrice().toPlainString())
                .toList());
    }

    /** The first band's unit price. */
    public BigDecimal firstPrice() {
        return bands.get(0).unitPrice();
    }

    /**
     * What the given quantity costs, starting from the first band: each band's units at that band's
     * price, rounded half up to the given number of decimals (2, the cent; 0 for whole yen).
     */
    public BigDecimal total(BigDecimal qty, int scale) {
        return charge(BigDecimal.ZERO, qty, scale);
    }

    /**
     * What the given quantity costs when the given number of units have already gone through the
     * bands before it: each of its units at the price of the band it falls in, the exact charge
     * rounded half up to the given number of decimals.
     */
    public BigDecimal charge(BigDecimal before, BigDecimal qty, int scale) {
        return exact(before.add(qty)).subtract(exact(before)).setScale(scale, RoundingMode.HALF_UP);
    }

    /** What the given quantity costs from the first band, unrounded. */
    private BigDecimal exact(BigDecimal qty) {
        BigDecimal left = qty;
        BigDecimal total = BigDecimal.ZERO;
        for (int i = 0; i < bands.size() && left.signum() > 0; i++) {
            Band band = bands.get(i);
            boolean last = band.units() == null || i == bands.size() - 1;
            BigDecimal units = last ? left : left.min(band.units());
            total = total.add(units.multiply(band.unitPrice()));
            left = left.subtract(units);
        }
        return total;
    }
}

